import java.util.Arrays;
import java.util.NoSuchElementException;

public class Solution {
    static class MinHeap {
        private int[] a = new int[8];
        private int n;

        MinHeap() {}

        // Build bottom-up: a maioria dos nós está perto das folhas e desce pouco → O(n).
        MinHeap(int[] valores) {
            a = Arrays.copyOf(valores, Math.max(8, valores.length));
            n = valores.length;
            for (int i = n / 2 - 1; i >= 0; i--) siftDown(i);
        }

        void offer(int v) {
            if (n == a.length) a = Arrays.copyOf(a, a.length * 2);
            a[n] = v;
            siftUp(n++);
        }

        int poll() {
            int topo = peek();
            a[0] = a[--n];
            if (n > 0) siftDown(0);
            return topo;
        }

        int peek() {
            if (n == 0) throw new NoSuchElementException();
            return a[0];
        }

        int size() { return n; }

        private void siftUp(int i) {
            while (i > 0 && a[(i - 1) / 2] > a[i]) {
                swap(i, (i - 1) / 2);
                i = (i - 1) / 2;
            }
        }

        private void siftDown(int i) {
            while (true) {
                int menor = i, e = 2 * i + 1, d = 2 * i + 2;
                if (e < n && a[e] < a[menor]) menor = e;
                if (d < n && a[d] < a[menor]) menor = d;
                if (menor == i) return;
                swap(i, menor);
                i = menor;
            }
        }

        private void swap(int i, int j) { int t = a[i]; a[i] = a[j]; a[j] = t; }
    }
}

