import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

import java.util.*;

class SolutionTest {
    @Test void ordemCrescente() {
        var h = new Solution.MinHeap();
        for (int v : new int[]{5, 3, 8, 1, 9, 2, 2}) h.offer(v);
        assertEquals(1, h.peek());
        int[] out = new int[7];
        for (int i = 0; i < 7; i++) out[i] = h.poll();
        assertArrayEquals(new int[]{1, 2, 2, 3, 5, 8, 9}, out);
        assertThrows(NoSuchElementException.class, h::poll);
    }

    @Test void buildEmLote() {
        var h = new Solution.MinHeap(new int[]{9, 4, 7, 1, -2, 6, 5});
        assertEquals(7, h.size());
        assertEquals(-2, h.poll());
        assertEquals(1, h.poll());
        h.offer(0);
        assertEquals(0, h.poll());
        assertEquals(4, h.poll());
    }

    @Test void aleatorioContraPriorityQueue() {
        var rnd = new Random(3);
        int[] base = rnd.ints(50_000, -1000, 1000).toArray();
        var h = new Solution.MinHeap(base);
        var ref = new PriorityQueue<Integer>();
        for (int v : base) ref.add(v);
        for (int i = 0; i < 100_000; i++) {
            if (rnd.nextInt(3) > 0 || ref.isEmpty()) {
                int v = rnd.nextInt();
                h.offer(v);
                ref.add(v);
            } else assertEquals((int) ref.poll(), h.poll());
        }
        assertEquals(ref.size(), h.size());
    }
}

