import java.util.*;

public class Solution {
    static class Mediana {
        private final PriorityQueue<Integer> menores = new PriorityQueue<>(Comparator.reverseOrder()); // max-heap
        private final PriorityQueue<Integer> maiores = new PriorityQueue<>();                          // min-heap

        // Invariante: todo menor <= todo maior, e menores tem o mesmo tamanho ou 1 a mais.
        void adicionar(int x) {
            menores.offer(x);
            maiores.offer(menores.poll());
            if (maiores.size() > menores.size()) menores.offer(maiores.poll());
        }

        double mediana() {
            if (menores.isEmpty()) throw new IllegalStateException("vazio");
            if (menores.size() > maiores.size()) return menores.peek();
            return ((long) menores.peek() + maiores.peek()) / 2.0;
        }
    }
}

