import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

import java.util.*;

class SolutionTest {
    @Test void sequencia() {
        var m = new Solution.Mediana();
        m.adicionar(5);  assertEquals(5.0, m.mediana());
        m.adicionar(15); assertEquals(10.0, m.mediana());
        m.adicionar(1);  assertEquals(5.0, m.mediana());
        m.adicionar(3);  assertEquals(4.0, m.mediana());
    }

    @Test void vazio() {
        assertThrows(IllegalStateException.class, () -> new Solution.Mediana().mediana());
    }

    @Test void extremosSemOverflow() {
        var m = new Solution.Mediana();
        m.adicionar(Integer.MAX_VALUE);
        m.adicionar(Integer.MAX_VALUE);
        assertEquals((double) Integer.MAX_VALUE, m.mediana());
        m.adicionar(Integer.MIN_VALUE);
        m.adicionar(Integer.MIN_VALUE);
        assertEquals(-0.5, m.mediana());
    }

    @Test void aleatorio() {
        var rnd = new Random(11);
        var m = new Solution.Mediana();
        List<Integer> ref = new ArrayList<>();
        for (int i = 0; i < 2000; i++) {
            int x = rnd.nextInt(1000);
            m.adicionar(x);
            ref.add(x);
            if (i % 97 == 0) {
                List<Integer> s = new ArrayList<>(ref);
                Collections.sort(s);
                int k = s.size();
                double esperado = k % 2 == 1 ? s.get(k / 2) : (s.get(k / 2 - 1) + s.get(k / 2)) / 2.0;
                assertEquals(esperado, m.mediana());
            }
        }
    }
}
